$(document).ready(function(){$("#fileSharingSettings button.pop-up").click(function(){var e=$(this).data("url");if(e){var i=screen.width/2-300,t=screen.height/2-200;window.open(e,"name","width=600, height=400, top="+t+", left="+i)}}),$("#oca-files-sharing-add-to-your-website").click(function(){$("#oca-files-sharing-add-to-your-website-expanded").slideDown()})});